-- =====================================================================
-- M03 — Donnees : marques et modeles de motos (source vPIC / NHTSA).
--
-- Jeu de donnees du DOMAINE PUBLIC : « Vehicle Product Information Catalog » de la
-- NHTSA (ministere des transports des Etats-Unis), API publique sans cle, donnees
-- produites par une administration federale americaine (domaine public, librement
-- reutilisables). motoplanete.com n'est PAS recopie : voir 20261005100000 et la
-- decision M-49.
--
-- Extraction du 2026-10-05, en deux passes :
--   * marques : GetMakesForVehicleType/motorcycle (1687 marques) ;
--   * 61 marques connues (celles qu'on voit au comptoir) : GetModelsForMakeIdYear
--     par millesime 1995-2027 avec le filtre « motorcycle » -> modeles de MOTO
--     uniquement (pas les voitures de BMW, Honda, Suzuki, Triumph...) ET annees de
--     commercialisation connues (1943 modeles) ;
--   * autres marques : GetModelsForMakeId (tous millesimes, sans annee connue).
-- Les marques sans aucun modele sont ecartees.
--
-- Rejouable : vehicle_catalog_load est idempotent (conflit sur le slug de la marque et
-- sur le couple marque+modele), aucune suppression. 1667 marques, 9973 modeles.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Correctif du chargeur avant le lot : fusionner les annees par min/max.
-- ---------------------------------------------------------------------
-- Deux modeles differents peuvent se normaliser en une seule cle (« Osa » et
-- « Osa+ » -> « osa ») : la mise a jour doit alors ELARGIR la plage d'annees,
-- sinon year_to peut passer sous year_from et la contrainte saute.
create or replace function public.vehicle_catalog_load(_rows jsonb)
returns table (brands integer, models integer)
language plpgsql security definer set search_path = public, pg_temp as $fn$
declare
  r        jsonb;
  m        jsonb;
  v_brand  uuid;
  v_slug   text;
  n_brands integer := 0;
  n_models integer := 0;
begin
  if jsonb_typeof(_rows) <> 'array' then
    raise exception 'vehicle_catalog_load : un tableau est attendu';
  end if;

  for r in select value from jsonb_array_elements(_rows) loop
    v_slug := public.vehicle_slug(r->>'brand');
    continue when v_slug is null;

    insert into public.vehicle_brands (slug, name, source, source_ref, is_popular)
    values (
      v_slug, btrim(r->>'brand'),
      coalesce(nullif(r->>'source', ''), 'manuel'),
      nullif(r->>'source_ref', ''),
      coalesce((r->>'popular')::boolean, false)
    )
    on conflict (slug) do update
      set name       = excluded.name,
          source     = excluded.source,
          source_ref = coalesce(excluded.source_ref, vehicle_brands.source_ref),
          is_popular = vehicle_brands.is_popular or excluded.is_popular,
          updated_at = now()
    returning id into v_brand;
    n_brands := n_brands + 1;

    for m in select value from jsonb_array_elements(coalesce(r->'models', '[]'::jsonb)) loop
      continue when public.vehicle_slug(m->>'name') is null;
      insert into public.vehicle_models (brand_id, slug, name, year_from, year_to, displacement_cc, source, source_ref)
      values (
        v_brand, public.vehicle_slug(m->>'name'), btrim(m->>'name'),
        nullif(m->>'year_from', '')::smallint,
        nullif(m->>'year_to', '')::smallint,
        nullif(m->>'displacement_cc', '')::integer,
        coalesce(nullif(r->>'source', ''), 'manuel'),
        nullif(m->>'source_ref', '')
      )
      on conflict (brand_id, slug) do update
        set name            = excluded.name,
            year_from       = least(coalesce(excluded.year_from, vehicle_models.year_from),
                                    coalesce(vehicle_models.year_from, excluded.year_from)),
            year_to         = greatest(coalesce(excluded.year_to, vehicle_models.year_to),
                                       coalesce(vehicle_models.year_to, excluded.year_to)),
            displacement_cc = coalesce(excluded.displacement_cc, vehicle_models.displacement_cc),
            updated_at      = now();
      n_models := n_models + 1;
    end loop;
  end loop;

  update public.vehicle_brands b
     set model_count = c.n, updated_at = now()
    from (select b2.id, (select count(*) from public.vehicle_models vm where vm.brand_id = b2.id) as n
            from public.vehicle_brands b2) c
   where c.id = b.id and b.model_count <> c.n;

  return query select n_brands, n_models;
end;
$fn$;
revoke all on function public.vehicle_catalog_load(jsonb) from public, anon, authenticated;
grant execute on function public.vehicle_catalog_load(jsonb) to service_role;

