-- « AUTRE » n'est pas une marque : la saisie libre a sa propre file.
delete from public.vehicle_models where brand_id in (select id from public.vehicle_brands where slug = 'autre');
delete from public.vehicle_brands where slug = 'autre';

-- Voitures trouvees dans nos fiches moto (erreurs de saisie) : masquees, pas supprimees
-- (elles restent sur les fiches). Seulement celles qu'aucune source publique ne confirme
-- comme constructeur de motos (source encore 'dms' apres le chargement vPIC).
update public.vehicle_brands set is_active = false, updated_at = now()
 where source = 'dms'
   and slug in ('alfa romeo', 'porsche', 'range rover', 'vw', 'volkswagen', 'audi', 'mercedes', 'opel', 'ford');

-- Marques mises en avant avant toute recherche : la liste courte historique de
-- l'inscription, plus Ducati (qui a son parcours dedie) et les marques citees par le
-- client. Les autres restent accessibles par la recherche.
update public.vehicle_brands set is_popular = true
 where slug in (
   'ducati','aprilia','bmw','harley davidson','honda','husqvarna','indian','kawasaki',
   'ktm','moto guzzi','mv agusta','royal enfield','suzuki','triumph','yamaha','cfmoto',
   'piaggio','vespa','benelli','beta','can am','fantic','gasgas','keeway','kymco',
   'norton','qj motor','sherco','swm','sym','voge','zero motorcycles','zontes','segway'
 );
